import { generateBioFromAnswers } from '~/client';
import type { GenerateBioResponse, GenerateBioRequest } from '~/client';

export const useGenerateBio = defineMutation(() => {
  const {
    mutateAsync: generateBio,
    asyncStatus,
    error,
    status,
    reset,
  } = useMutation({
    mutation: (generateBioForm: GenerateBioRequest): Promise<GenerateBioResponse> =>
      generateBioFromAnswers({
        composable: '$fetch',
        body: generateBioForm,
      }),
  });

  return {
    status,
    error,
    reset,
    generateBio,
    isGeneratingBio: computed(() => asyncStatus.value === 'loading'),
  };
});
